{
  "checked_on": "2026-09-28",
  "method": "Three exact primary pages opened through web tool; short original paraphrases only; no integration or benchmark",
  "sources": [
    {
      "id": "RW10-FIDES",
      "url": "https://devblogs.microsoft.com/agent-framework/fides/",
      "date": "2026-05-20",
      "sections": "Labels, policy before tools, current limitations"
    },
    {
      "id": "RW10-IFC",
      "url": "https://commandline.microsoft.com/information-flow-control-moving-toward-secure-autonomous-agents/",
      "date": "2026-06-16",
      "sections": "Label, propagate, check; prototypes and boundaries"
    },
    {
      "id": "RW11",
      "url": "https://www.apple.com/fr/newsroom/2026/08/apple-introduces-m6-and-m5-ultra-for-a-big-leap-in-performance-and-ai-compute/",
      "date": "2026-08-25",
      "sections": "Manufacturer announcement; local computation/unified memory only"
    }
  ],
  "not_claimed": [
    "Raw article reproduction",
    "Independent experiments",
    "Speed or security comparison",
    "Apple/Sentinel adapter"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://hedgehog-os.local/schemas/temporal_query.schema.json",
  "title": "TemporalQuery",
  "type": "object",
  "required": [
    "as_of",
    "freshness_bias"
  ],
  "properties": {
    "as_of": {
      "$ref": "common.schema.json#/$defs/Timestamp"
    },
    "time_range": {
      "$ref": "common.schema.json#/$defs/TimeRange"
    },
    "freshness_bias": {
      "enum": [
        "historical_as_of",
        "prefer_recent",
        "strict_current",
        "ignore_time_only_if_policy_allows"
      ]
    },
    "max_age_seconds": {
      "type": "integer",
      "minimum": 0
    },
    "freshness_required": {
      "enum": [
        "low",
        "normal",
        "high",
        "real_time"
      ]
    }
  },
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://hedgehog-os.local/schemas/common.schema.json",
  "title": "Hedgehog OS MVP Common Definitions",
  "type": "object",
  "required": [],
  "properties": {},
  "additionalProperties": false,
  "$defs": {
    "Id": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]*$"
    },
    "Timestamp": {
      "type": "string",
      "format": "date-time"
    },
    "NonEmptyString": {
      "type": "string",
      "minLength": 1
    },
    "TimeRange": {
      "type": "object",
      "required": [
        "from",
        "to"
      ],
      "properties": {
        "from": {
          "anyOf": [
            {
              "$ref": "#/$defs/Timestamp"
            },
            {
              "type": "null"
            }
          ]
        },
        "to": {
          "anyOf": [
            {
              "$ref": "#/$defs/Timestamp"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "additionalProperties": false
    },
    "RiskScore": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "Score01": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "TraceRef": {
      "type": "object",
      "required": [
        "trace_id"
      ],
      "properties": {
        "trace_id": {
          "$ref": "#/$defs/Id"
        },
        "span_id": {
          "$ref": "#/$defs/Id"
        },
        "kind": {
          "$ref": "#/$defs/NonEmptyString"
        }
      },
      "additionalProperties": false
    },
    "ProvenanceRef": {
      "type": "object",
      "required": [
        "source"
      ],
      "properties": {
        "source": {
          "enum": [
            "user",
            "system",
            "needle",
            "local_drs",
            "external_drs",
            "fallback",
            "executor",
            "validator"
          ]
        },
        "source_id": {
          "$ref": "#/$defs/Id"
        },
        "trace_ref": {
          "$ref": "#/$defs/TraceRef"
        }
      },
      "additionalProperties": false
    },
    "Cost": {
      "type": "object",
      "required": [],
      "properties": {
        "tokens": {
          "type": "integer",
          "minimum": 0
        },
        "walltime_ms": {
          "type": "integer",
          "minimum": 0
        },
        "toolcalls": {
          "type": "integer",
          "minimum": 0
        },
        "money": {
          "type": "number",
          "minimum": 0
        },
        "currency": {
          "type": "string",
          "minLength": 3,
          "maxLength": 3
        }
      },
      "additionalProperties": false
    },
    "EvidenceItem": {
      "type": "object",
      "required": [
        "kind",
        "summary"
      ],
      "properties": {
        "kind": {
          "enum": [
            "drs_record",
            "needle",
            "schema",
            "policy",
            "trace",
            "simulated_executor",
            "fractal_dag_executor",
            "audit",
            "manual"
          ]
        },
        "summary": {
          "$ref": "#/$defs/NonEmptyString"
        },
        "ref_id": {
          "$ref": "#/$defs/Id"
        },
        "confidence": {
          "$ref": "#/$defs/Score01"
        }
      },
      "additionalProperties": false
    },
    "PolicyRef": {
      "type": "object",
      "required": [
        "policy_id"
      ],
      "properties": {
        "policy_id": {
          "$ref": "#/$defs/Id"
        },
        "version": {
          "$ref": "#/$defs/NonEmptyString"
        }
      },
      "additionalProperties": false
    },
    "ModeRef": {
      "type": "object",
      "required": [
        "mode"
      ],
      "properties": {
        "mode": {
          "enum": [
            "default",
            "strict",
            "explore",
            "dry_run",
            "local_only",
            "review",
            "test"
          ]
        },
        "autonomy": {
          "enum": [
            "manual",
            "confirm_before_action",
            "bounded_auto"
          ]
        }
      },
      "additionalProperties": false
    },
    "Domain": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[a-z][a-z0-9_:-]*$"
    },
    "Status": {
      "enum": [
        "draft",
        "active",
        "accepted",
        "rejected",
        "quarantined",
        "archived",
        "no_update"
      ]
    }
  }
}

