  "cases": [
    {
      "case_id": "CASE-SUPPLIER",
      "destination": "CROSS_CASE_CHAPTER.md#case-supplier-make-the-permitted-part-useful",
      "question": "Can Supplier A make useful scoped progress while Supplier B and shipment evidence remain unresolved?",
      "profile": "two_domain_all_real_sealed_evidence_program_v01_s1_supplier_live; deterministic S2 negative rows kept separate",
      "source_refs": [
        "TD-NAV",
        "X1",
