    {
      "case_id": "CASE-AIRLINE",
      "destination": "CROSS_CASE_CHAPTER.md#case-airline-coordinate-without-a-superior-owner",
      "question": "Can customer, airline and bank coordinate a bounded transaction while each keeps its own decision?",
      "profile": "tri_party_airline_live_semantic_lane_v01:attempt_04; older airline_all_real_full_stack_v01 matrix is a distinct lineage",
      "source_refs": [
        "TD-NAV",
        "X1",
