        "A-MATRIX"
      ],
      "source_identity": {
        "execution_head": "71764c8b41f26e94b9cfdc1e821f7d8e15df4149",
        "run_id": "tri_party_airline_live_semantic_lane_v01:attempt_04",
        "transaction_id": "tri_airline_purchase:PAR-LIM:2026-08-12:client_001"
      },
      "changed": "Different business-owner composition and offer-specific semantic selection; recommendation and selected offer are recorded, not a randomized causal benchmark.",
      "stayed": "ClientRoot, AirlineRoot and BankRoot retain distinct dependencies and ownership. Projections and receipts do not create permission.",
      "owners": [
        "root:client_os_001",
        "root:mock_airline_al",
        "root:mock_bank_a"
      ],
      "useful_outcome": "Selected mock offer 001; one bounded mock Corridor, three evidence-only receipts, separate Root finals.",
      "lawful_neighbor": "Attempt 04 selected-offer transaction in A-REPORT",
      "adverse_neighbor": "A-MATRIX C22-C23 preserve older failed-package history and distinct recovery. This is a separate-profile historical neighbor, not an attempt-04 mutation.",
      "evidence_cells": {
        "owner_coordination": "recorded-historical",
        "model_origin": "recorded-historical: twelve real_provider calls at 71764c8...",
        "failure_recovery": "recorded-historical: older full-stack committed_audit_of_local_package attribution",
        "cross_case_owner_view": "interpretation",
        "current_observation": "observed-current: JSON values and hashes only",
        "signature_verification_C24": "not-demonstrated: recorded false",
        "real_booking_payment": "not-demonstrated"
      },
      "observer_and_time": "Attempt-04 safe reporter at recorded execution head; 2026-08-12 is the travel date, not inferred collection time. Older matrix points to a701743/ec50c1f sources. No new audit or call on 2026-09-27.",
      "limits": [
        "Safe reviewer summary is not raw response or present fare truth.",
        "No real airline/bank integration.",
        "Do not merge attempt 03, attempt 04, old full-stack recovery or Atlas selected-offer/hold-only records."
      ],
      "verification_route": "Inspect A-REPORT /actors/2/safe_projection, /bsep/projections, /root_finals, /corridor and /receipts; inspect A-MATRIX by claim_id C22-C24 with its own source_commit fields.",
      "field_facts": [
        {
          "source": "A-REPORT",
          "pointer": "/execution_head",
          "value": "71764c8b41f26e94b9cfdc1e821f7d8e15df4149"
